- `apps/graph-manager/README.md` (`## Security`, line 364) — add one bullet about API tokens.

## Patterns to follow

**Route module (mirror routes/reviewers.ts, routes/pr.ts):**
```ts
export async function tokenRoutes(app: FastifyInstance, ctx: AppContext): Promise<void> {
  app.get("/api/tokens", async () => ({ tokens: listTokens(ctx.store.get()) }));
  app.post("/api/tokens", async (req, reply) => {
    const body = createBody.parse(req.body ?? {}); // ZodError → 400 by app.ts's error handler
    ...
    return reply.code(201).send({ id, name, scopes, createdAt, createdBy: "admin", token });
  });
  app.delete<{ Params: { id: string } }>("/api/tokens/:id", async (req, reply) => {
    if (!ctx.store.get().apiTokens[req.params.id]) return reply.code(404).send({ error: "unknown token" });
    await ctx.store.update((d) => { delete d.apiTokens[req.params.id]; });
    return reply.code(204).send();
  });
}
```

**Store schema (mirror store.ts:27 and 20–25):**
```ts
/** API tokens for /api/v1 (docs/prd/automation-api.md). Only the SHA-256 hex of the token is kept. */
apiTokens: z
  .record(
    z.string(),
    z.object({
      name: z.string(),
      hash: z.string().regex(/^[0-9a-f]{64}$/),
      scopes: z.array(z.enum(API_SCOPES)),
      createdAt: z.string(),
      lastUsedAt: z.string().optional(),
      createdBy: z.literal("admin"),
    }),
  )
  .default({}),
```
Define `API_SCOPES` in a new `src/server/tokens.ts` (pure helpers, no Fastify) and import it in store.ts. `tokens.ts` must not import store.ts (avoid a cycle); give its functions plain parameters.

**Constant-time compare (mirror auth.ts:46–50):**
```ts
export function hashToken(token: string): string { return createHash("sha256").update(token).digest("hex"); }
/** The id of the stored token whose hash matches, compared in constant time over every entry (no early exit). */
export function findToken(tokens: Record<string, { hash: string }>, token: string): string | undefined {
  const given = Buffer.from(hashToken(token), "hex");
  let found: string | undefined;
  for (const [id, t] of Object.entries(tokens)) {
    const stored = Buffer.from(t.hash, "hex");
    if (stored.length === given.length && timingSafeEqual(stored, given) && found === undefined) found = id;
  }
  return found;
}
export const newToken = (): string => `gmt_${randomBytes(32).toString("base64url")}`;
```
Token ids: `randomBytes(8).toString("hex")`.

**Per-request auth (no Fastify type augmentation):** keep a module-level `WeakMap<FastifyRequest, ApiAuth>` in auth.ts and export a reader:
```ts
export type ApiAuth = { kind: "admin" } | { kind: "token"; id: string; scopes: ApiScope[] };
const apiAuth = new WeakMap<FastifyRequest, ApiAuth>();
/** Who called a /api/v1 route: the cookie session (every scope) or a token. Undefined outside /api/v1. */
export function apiAuthOf(req: FastifyRequest): ApiAuth | undefined { return apiAuth.get(req); }
/** preHandler: 403 `missing scope <scope>` unless the caller has it. */
export function requireScope(scope: ApiScope) {
  return async (req: FastifyRequest, reply: FastifyReply) => {
    const a = apiAuth.get(req);
    if (a?.kind === "token" && !a.scopes.includes(scope)) return reply.code(403).send({ error: `missing scope ${scope}` });
  };
}
```
Route usage (later slices): `app.get("/api/v1/runs", { preHandler: requireScope("runs:read") }, handler)`.

**The hook (change auth.ts:119–126):** before the Origin check, handle v1 bearer:
```ts
const pathname = req.url.split(/[?#]/, 1)[0] ?? "";
const v1 = pathname === "/api/v1" || pathname.startsWith("/api/v1/");
const bearer = v1 ? bearerOf(req.headers.authorization) : undefined; // "Bearer <x>" (case-insensitive scheme) → x
if (bearer !== undefined) {
  const data = ctx.store.get();
  const id = findToken(data.apiTokens, bearer);
  const tok = id === undefined ? undefined : data.apiTokens[id];
  if (id === undefined || !tok) return reply.code(401).send({ error: "invalid token" });
  apiAuth.set(req, { kind: "token", id, scopes: tok.scopes });
  touch(id, tok.lastUsedAt); // fire-and-forget store.update, at most once a minute per token
  return; // no Origin check, no cookie needed
}
// …existing Origin check and session check unchanged…
// after a valid session: if (v1) apiAuth.set(req, { kind: "admin" });
```
`touch`: skip when `lastUsedAt` is less than 60 000 ms old; otherwise `void ctx.store.update((d) => { const t = d.apiTokens[id]; if (t) t.lastUsedAt = new Date().toISOString(); }).catch(() => undefined)`; also keep an in-memory `Map<id, ms>` of the last write so parallel requests within the minute don't each queue a write.

**Error handling:** route errors are `reply.code(n).send({ error: "…" })`; the zod error handler produces 400s. Never log or echo a token or hash.

**Test pattern:** server tests are vitest files next to the code (`*.test.ts`) using `appWithLogin()` and `app.inject({ method, url, headers: { cookie } | { authorization: "Bearer …" }, payload })`. Web tests are `// @vitest-environment jsdom` files using `@testing-library/react`, `vi.stubGlobal("fetch", vi.fn(...))`, wrappers `ToastProvider` (+ `OverviewProvider` when the page uses `useOverview`).

## Step-by-step tasks

